import re
from lxml import etree
from os import path
from time import sleep
from robot.libraries.BuiltIn import BuiltIn
from robot.api import logger
from ute_fsmaccess import ute_fsmaccess
from ta5g_global_var import ENB0_LMP_IP
from ta5g_admin_operations import ta_admin_common_operations


PM_COUNTERS_COMMAND = 'ls /ram/PM.BTS* 2>/dev/null | xargs -n1 basename 2>/dev/null;:'


class CountersResources(object):
    def get_pm_counter_value(self, counter, localmoid, filepath, pmqap=None):
        """
        :param counter: Counter ID, i.e.  M8005C345
        :param localmoid: localMOid from PM file, ie. DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09
        :param filepath: unpacked file location (xml) with counters values
        :return: list of counter's values. 4-element list in case of full file, 1-element list in case of RAW file
        """
        localmoid = self.change_local_moid_for_sbts(localmoid)
        xml_tree = self._get_ast(filepath)
        counter_objects = self._get_all_counter_objects(xml_tree, counter)
        if isinstance(localmoid, list):
            counter_value = self._get_all_localmoids_sbts(counter_objects, localmoid)
        else:
            counter_value = self._get_all_localmoids(counter_objects, localmoid, pmqap)
        return counter_value

    def check_if_counter_exists(self, counter, localmoid, filepath):
        """
        :param counter: Counter ID, i.e.  M8005C345
        :param localmoid: localMOid from PM file, ie. DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09
        :param filepath: unpacked file location (xml) with counters values
        :return: True or False if counter exists or not
        """
        values = self.get_pm_counter_value(counter, localmoid, filepath)
        return True if values else False

    def verify_any_pm_counter_values(self, counter_id, expected, localmoid, filepath):
        """
        :param counter_id: Counter ID, i.e.  M8005C345
        :param expected: expected value of counter
        :param localmoid: localMOid from PM file, ie. DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09
        :param filepath: unpacked file location (xml) with counters values
        """

        BuiltIn().log_to_console("Counter {} verification".format(counter_id))

        pm_counter_values_list = self.get_pm_counter_value(counter_id, localmoid, filepath)
        value_found = any([value == int(expected) for value in pm_counter_values_list])  # noqa

        BuiltIn().should_be_true(value_found, self._prepare_err_msg(counter_id, expected, filepath, localmoid))

    def verify_multiple_counters_value(self, counters_ids, expected, localmoid, filepath):
        """
        :param counter_ids: Counter IDs list, i.e.  [M8005C345, M8005C45]
        :param expected: expected value of counters
        :param localmoid: localMOid from PM file, ie. DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09
        :param filepath: unpacked file location (xml) with counters values
        """  # noqa
        for counter_id in counters_ids:
            self.verify_any_pm_counter_values(counter_id, expected, localmoid, filepath)

    @staticmethod  # noqa
    def _get_all_localmoids(counter_objects, localmoid, pmqap=None):  # noqa
        counter_value = []
        if not pmqap:
            for element in counter_objects:
                for grandelement in element.getparent().getparent().iter():
                    if grandelement.text is not None and re.match('.*' + localmoid + r'\Z', grandelement.text):
                        counter_value.append(int(float(element.text)))
            return counter_value
        else:
            for element in counter_objects:
                localmoid_check = False
                pmqap_check = False
                for grandelement in element.getparent().getparent().iter():
                    if grandelement.text is not None and re.match('.*' + localmoid + r'\Z', grandelement.text):
                        localmoid_check = True
                    elif grandelement.text is not None and re.match('.*' + pmqap + r'\Z', grandelement.text):
                        pmqap_check = True
                if localmoid_check and pmqap_check:
                    counter_value.append(int(float(element.text)))
            return counter_value

    @staticmethod
    def _get_all_localmoids_sbts(counter_objects, localmoid):
        counter_value = []
        for element in counter_objects:
            for grandelement in element.getparent().getparent().iter(tag='DN'):
                if re.match(localmoid[0], grandelement.text):
                    siblings = [grandelement.text] + [
                        x.getchildren()[0].text for x in grandelement.getparent().itersiblings(tag='MO')
                    ]
                    if localmoid == siblings:
                        counter_value.append(int(element.text))
        logger.debug(("Counter Values: {}".format(counter_value)))
        return counter_value

    @staticmethod
    def _get_all_counter_objects(xml_tree, counter):
        elements = []
        for element in xml_tree:
            if element.tag == counter:
                elements.append(element)
        return elements

    @staticmethod
    def _get_ast(filepath):
        if not path.exists(filepath):
            raise IOError("File {} not exists".format(filepath))

        root = etree.parse(filepath)
        return root.iter()

    @staticmethod
    def change_local_moid_for_sbts(local_moid):
        logger.debug("Original local MOID: {}".format(local_moid))
        prefix = ['PLMN-PLMN']
        mrbts_nr = re.search(r'LNBTS-(\d+)', local_moid)
        local_moid = re.sub(
            r'(DN:NE-)', 'PLMN-PLMN/MRBTS-{}/'.format(mrbts_nr.group(1) if mrbts_nr else '1'), local_moid
        )
        local_moid = re.split(r'\/(?=MCC)', local_moid, 1)
        modified_moid = [local_moid[0]]
        if len(local_moid) == 2:
            second_part = local_moid[1].split('/')
            if len(second_part) == 2:
                moid_2 = '/'.join(prefix + second_part)
                modified_moid.append(moid_2)
            elif 3 <= len(second_part) < 5:
                moid_2 = '/'.join(prefix + second_part[0:2])
                moid_3 = '/'.join(prefix + second_part[2:])
                modified_moid.extend((moid_2, moid_3))
            elif len(second_part) == 5:
                moid_2 = '/'.join(prefix + second_part[0:2])
                moid_3 = '/'.join(prefix + [second_part[2]])
                moid_4 = '/'.join(prefix + second_part[3:])
                modified_moid.extend((moid_2, moid_3, moid_4))
            logger.debug("** MOID UPDATED: {} **".format(modified_moid))
            return modified_moid
        return local_moid[0] if isinstance(local_moid, list) else local_moid

    @staticmethod
    def _prepare_err_msg(counter_id, expected, filepath, local_moid):
        return "Expected value '{}' has not been found for counter '{}' in localMOid {} in file '{}'".format(
            expected, counter_id, local_moid, filepath
        )

    def wait_for_new_pm_filename(self, raw_file, remote_host=None, timeout=4000, host=ENB0_LMP_IP):  # noqa: C901
        """
        :param raw_file:  If TRUE then method will wait for RAW file creation
        :param remote_host:  Useful when working on X2-connected test lines
        :param timeout:  How many seconds function waits for new PM file, when its exceded raises timeout error, default 30min
        :return: Newly created RAW of full PM counter filename
        """

        file_ready = False
        unzip_timeout = 60
        wrn_print = ('PM file is unzippable after timeout: {}s').format(unzip_timeout)
        fsm_ssh = ute_fsmaccess()
        fsm_ssh.setup_enb_fsm_access(host=host, remote_host=remote_host)
        try:
            if not remote_host:
                old_ram_content = fsm_ssh.execute_command_on_enb(PM_COUNTERS_COMMAND).split()
            else:
                old_ram_content = ta_admin_common_operations.execute_command_on_remote_host(gnb_ip=ENB0_LMP_IP, vm_ip=remote_host,
                    command_to_execute=PM_COUNTERS_COMMAND)  # noqa
                old_ram_content = old_ram_content.split()
            while not file_ready:
                self._unzip_timeout(timeout, "Timeout, too long time without new PM file on ENB")
                sleep(10)
                timeout -= 10
                if not remote_host:
                    new_ram_content = fsm_ssh.execute_command_on_enb(PM_COUNTERS_COMMAND).split()
                else:
                    new_ram_content = ta_admin_common_operations.execute_command_on_remote_host(gnb_ip=ENB0_LMP_IP, vm_ip=remote_host,
                    command_to_execute=PM_COUNTERS_COMMAND)
                    new_ram_content = new_ram_content.split()
                if new_ram_content:
                    file_ready, difference = self._is_new_file_ready(old_ram_content, new_ram_content, raw_file)
            while True:
                self._unzip_timeout(unzip_timeout, wrn_print)
                if not remote_host:
                    msg_rc = fsm_ssh.execute_command_on_enb(cmd="gunzip -t /ram/{}".format(difference), return_rc=True)
                else:
                    msg_rc = ta_admin_common_operations.execute_command_on_remote_host(gnb_ip=ENB0_LMP_IP, vm_ip=remote_host,
                    command_to_execute="gunzip -t /ram/{}".format(difference))
                    sleep(5)
                    break
                if msg_rc[1] == 0:
                    break
                logger.info('File is unzippable, try again after 5s : {}'.format(msg_rc[0]))
                sleep(5)
                unzip_timeout -= 5
            return difference
        finally:
            fsm_ssh.teardown_enb_fsm_access()

    @staticmethod
    def _unzip_timeout(timeout, msg):
        if timeout < 0:
            raise IOError(msg)

    def wait_for_new_rd_filename(self, raw_file, remote_host=None, timeout=4000, host=ENB0_LMP_IP):
        """
        :param raw_file:  If TRUE then method will wait for RAW file creation
        :param remote_host:  Useful when working on X2-connected test lines
        :param timeout:  How many seconds function waits for new RD file, when its exceded raises timeout error, default 30min
        :return: Newly created RAW of full RD counter filename
        """

        file_ready = False
        fsm_ssh = ute_fsmaccess()
        fsm_ssh.setup_enb_fsm_access(host=host, remote_host=remote_host)
        try:
            if not remote_host:
                old_ram_content = fsm_ssh.execute_command_on_enb(
                    'ls /ram/RD.BTS* 2>/dev/null | xargs -n1 basename 2>/dev/null;:'
                ).split()
            else:
                old_ram_content = ta_admin_common_operations.execute_command_on_remote_host(gnb_ip=ENB0_LMP_IP, vm_ip=remote_host,
                    command_to_execute=PM_COUNTERS_COMMAND)  # noqa
                old_ram_content = old_ram_content.split()
            while not file_ready:
                if timeout < 0:
                    raise IOError("Timeout, too long time without new PM file on ENB")
                sleep(10)
                timeout -= 10
                new_ram_content = fsm_ssh.execute_command_on_enb(
                    'ls /ram/RD.BTS* 2>/dev/null | xargs -n1 basename 2>/dev/null;:'
                ).split()
                if new_ram_content:
                    file_ready, difference = self._is_new_file_ready(old_ram_content, new_ram_content, raw_file)
            return difference
        finally:
            fsm_ssh.teardown_enb_fsm_access()

    @staticmethod
    def _is_new_file_ready(old_ram_content, new_ram_content, raw_file):
        difference = ''
        file_ready = True
        if new_ram_content[-1] not in old_ram_content:
            difference = new_ram_content[-1]
        if not difference or (raw_file and 'raw' not in difference) or (not raw_file and 'raw' in difference):
            file_ready = False
        return file_ready, difference

    def get_newest_pm_filename(self, raw_file, remote_host=None):
        """
        :param raw_file: If TRUE then method will return RAW filename
        :param remote_host: Useful when working on X2-connected test lines
        :return: RAW or full PM filename as string
        """
        pm_files = self.get_pm_files_list_from_ram_content(raw_file, remote_host)
        return max(pm_files) if pm_files else ''

    def get_pm_files_list_from_ram_content(self, raw_file, remote_host=None, host=ENB0_LMP_IP):
        """
        :param raw_file: If TRUE then method will return list with RAW filenames also
        :param remote_host: Useful when working on X2-connected test lines
        :return: list containing available pm counters files on eNB
        """

        fsm_ssh = ute_fsmaccess()
        fsm_ssh.setup_enb_fsm_access(host=host, remote_host=remote_host)
        try:
            if not remote_host:
                ram_content = fsm_ssh.execute_command_on_enb('ls /ram').split()
            else:
                ram_content = ta_admin_common_operations.execute_command_on_remote_host(gnb_ip=ENB0_LMP_IP, vm_ip=remote_host,
                                                                                        command_to_execute='ls /ram')
                ram_content = ram_content.split()
            pm_files = self._filter_pm_files_list_from_ram_content(ram_content, raw_file)
        finally:
            fsm_ssh.teardown_enb_fsm_access()
        return pm_files

    @staticmethod
    def _filter_pm_files_list_from_ram_content(ram_content, raw_file):
        pm_files = []
        for file_name in ram_content:
            if 'PM.BTS' not in file_name or (not raw_file and 'raw' in file_name):
                continue
            pm_files.append(file_name)
        return pm_files
